[CmdletBinding()] param()
$ErrorActionPreference='Stop';$baselineDirectory=$PSScriptRoot;$root=Split-Path -Parent (Split-Path -Parent $baselineDirectory);$docker='C:\Program Files\Docker\Docker\resources\bin\docker.exe';$container='akis-metadata-db-1';$db='akis_worker_test_'+[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();$made=$false;$settings=@{};Get-Content (Join-Path $root '.env')|Where-Object{$_ -match '^[A-Za-z_][A-Za-z0-9_]*='}|ForEach-Object{$n,$v=$_ -split '=',2;$settings[$n]=$v};$u=(&$docker exec $container sh -lc 'printf %s "$POSTGRES_USER"').Trim()
try{&$docker exec $container createdb -U $u $db;if($LASTEXITCODE){throw 'create failed'};$made=$true;foreach($f in Get-ChildItem $baselineDirectory/V0*.sql|Sort-Object Name){&$docker cp $f.FullName "${container}:/tmp/$($f.Name)"|Out-Null;&$docker exec $container psql -q -v ON_ERROR_STOP=1 -U $u -d $db -f "/tmp/$($f.Name)";if($LASTEXITCODE){throw $f.Name}};$vf=Join-Path $baselineDirectory 'verify-worker.sql';&$docker cp $vf "${container}:/tmp/verify-worker.sql"|Out-Null;&$docker exec $container psql -v ON_ERROR_STOP=1 -U $u -d $db -f '/tmp/verify-worker.sql';if($LASTEXITCODE){throw 'verify failed'};$env:SPRING_DATASOURCE_URL="jdbc:postgresql://localhost:$($settings['POSTGRES_PORT'])/$db";$env:SPRING_DATASOURCE_USERNAME=$u;$env:SPRING_DATASOURCE_PASSWORD=$settings['POSTGRES_PASSWORD'];&(Join-Path $root 'mvnw.cmd') -pl backend '-Dtest=CleanWorkerLeaseRepositoryIT,CleanProcedureExecutionJournalIT' test;if($LASTEXITCODE){throw 'repository test failed'};'Clean worker lease repository tests: PASS'}finally{if($made -and $db -match '^akis_worker_test_[0-9]+$'){&$docker exec $container dropdb --if-exists --force -U $u $db|Out-Null}}
